<?php
namespace App\Http\Controllers;
use App\Models\Product; use App\Models\Order; use Illuminate\Http\Request; use Illuminate\Support\Str; use Illuminate\Support\Facades\DB;
class CheckoutController extends Controller {
 public function index(){ $c=session('cart',[]);abort_if(!$c,redirect()->route('cart'));$products=Product::whereIn('id',array_keys($c))->get()->keyBy('id');$total=collect($c)->sum(fn($q,$id)=>($products[$id]->price??0)*$q);return view('checkout',compact('c','products','total'));}
 public function store(Request $r){$d=$r->validate(['customer_name'=>'required|string|max:120','phone'=>'required|string|max:30','address'=>'required|string|max:1000','city'=>'required|string|max:100','payment_method'=>'required|in:cod,bkash,nagad','payment_reference'=>'nullable|string|max:100']);$c=session('cart',[]);abort_if(!$c,redirect()->route('cart'));$ps=Product::whereIn('id',array_keys($c))->get()->keyBy('id');$items=[];$total=0;foreach($c as $id=>$qty){$p=$ps[$id]??null;abort_unless($p&&$p->is_active,422);if(!$p->is_dropship)abort_if($p->stock_qty<$qty,422,'Stock unavailable');$items[]=['product'=>$p->name,'qty'=>$qty,'price'=>(float)$p->price,'supplier'=>$p->supplier_name];$total+=$p->price*$qty;} $o=Order::create(['user_id'=>auth()->id(),'order_no'=>'MZ-'.strtoupper(Str::random(8)),'customer_name'=>$d['customer_name'],'phone'=>$d['phone'],'address'=>$d['address'],'city'=>$d['city'],'items_json'=>$items,'total'=>$total+80,'payment_method'=>$d['payment_method'],'payment_reference'=>$d['payment_reference']??null,'payment_status'=>'unpaid','status'=>'pending']);foreach($c as $id=>$qty)if(!$ps[$id]->is_dropship)$ps[$id]->decrement('stock_qty',$qty);session()->forget('cart');return redirect()->route('my.orders')->with('success','Order placed: '.$o->order_no);}
 public function orders(){ $orders=Order::where('user_id',auth()->id())->latest()->paginate(15);return view('orders',compact('orders'));}
}
